#!/usr/bin/env python3
import base64
import json
import shutil
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
FILES = {'quartz/scripts/render-copy-ready.mjs': ' ', 'quartz/scripts/render-copy-ready.test.mjs': '', 'quartz/scripts/copy-ready.test.mjs': '', 'quartz/scripts/verify-publication-package.mjs': '', 'quartz/scripts/verify-publication-package.test.mjs': '', '.github/scripts/validate_repository_contract.py': '', '.github/tests/repository_contract/test_repository_contract.py': ' ', 'quartz/PLATFORM-RENDITIONS.md': '**', 'content/research/notes/thinking-systems-platform-renditions.md': ''}

for relative, encoded in FILES.items():
    target = ROOT / relative
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_bytes(base64.b64decode(encoded))

shutil.rmtree(ROOT / "content/research/notes/thinking-systems-platform-assets", ignore_errors=True)

contract_path = ROOT / ".github/policy/repository-contract-change-coupling.json"
contract = json.loads(contract_path.read_text(encoding="utf-8"))
critical = {rule["path"]: rule for rule in contract["critical_files"]}
package_rule = critical["package.json"]
package_rule["required_text"] = [marker for marker in package_rule.get("required_text", []) if not marker.startswith('"pdf') and not marker.startswith('"publication:')]
script_values = {"pdf": "node quartz/scripts/export-pdf.mjs", "pdf:article": "node quartz/scripts/render-publication-pdf.mjs content/research/notes/thinking-systems-publication-draft.md --output dist/pdf/thinking-systems-when-the-controlled-object-changes.pdf", "pdf:working-paper": "node quartz/scripts/render-publication-pdf.mjs content/research/notes/open-engineering-specification-article-draft.md --output dist/pdf/uncertainty-architecture-thinking-systems-working-paper.pdf --no-split-dense", "pdf:verify:figure8": "node quartz/scripts/verify-publication-figure8.mjs", "publication:platforms": "node quartz/scripts/render-platform-renditions.mjs", "publication:protect-links": "node quartz/scripts/protect-platform-heading-links.mjs", "publication:furniture": "node quartz/scripts/render-platform-furniture.mjs", "publication:copy-ready": "node quartz/scripts/render-copy-ready.mjs", "publication:bundle": "npm run publication:assets && npm run publication:platforms && npm run publication:protect-links && npm run publication:furniture && npm run publication:copy-ready", "publication:verify-package": "node quartz/scripts/verify-publication-package.mjs"}
package_rule["required_json"] = [{"pointer": f"/scripts/{name}", "equals": value} for name, value in script_values.items()]
critical["quartz/scripts/render-copy-ready.mjs"]["required_text"] = ["embedLocalImages", "buildMediumUploadPlan", "medium_manual_upload_required", "medium_clipboard_images_supported: false", "embedded-data-uri-preview", "medium/upload/README.md", "data:image/png;base64", "manual-select-all-copy", "javascript_copy_controls: false"]
critical["quartz/scripts/render-copy-ready.test.mjs"]["required_text"] = ["copy-ready HTML embeds local images as data URIs", "copy-ready document exposes one article-only copy surface", "Medium upload plan is hero plus nine figures in deterministic order"]
critical["quartz/scripts/verify-publication-package.mjs"]["required_text"] = ["assertPlatformFigureInventory", "assertMediumUploadManifest", 'publication_state === "candidate"', "publication_ready === false", "Figure 8A and 8B must travel together", "Medium clipboard image transfer must not be claimed", "medium/upload/00-medium-hero.png", "copy-ready HTML contains obsolete copy controls"]
critical["quartz/scripts/verify-publication-package.test.mjs"]["required_text"] = ["platform verifier requires nine figures with Figure 8A and 8B coupled", "platform verifier rejects incomplete Figure 8 coupling", "Medium upload manifest requires ten ordered images plus instructions", "Medium upload manifest rejects any claim that clipboard images are supported"]
contract_path.write_text(json.dumps(contract, indent=2) + "\n", encoding="utf-8")

cases_path = ROOT / ".github/tests/repository_contract/cases.json"
cases_document = json.loads(cases_path.read_text(encoding="utf-8"))
cases = cases_document["cases"]
by_name = {case["name"]: case for case in cases}
by_name["explicit generic PDF entrypoint deletion is rejected"].update({"mutation": {"type": "delete_json_pointer", "path": "package.json", "pointer": "/scripts/pdf"}, "expected_error": "package.json: JSON pointer '/scripts/pdf'"})
by_name["curated working-paper command deletion is rejected"].update({"mutation": {"type": "delete_json_pointer", "path": "package.json", "pointer": "/scripts/pdf:working-paper"}, "expected_error": "package.json: JSON pointer '/scripts/pdf:working-paper'"})
for name in ["package script JSON formatting is ignored", "package script moved outside scripts is rejected"]:
    cases[:] = [case for case in cases if case["name"] != name]
cases.extend([{"name": "package script JSON formatting is ignored", "mutation": {"type": "format_json_compact", "path": "package.json"}, "expected_valid": True}, {"name": "package script moved outside scripts is rejected", "mutation": {"type": "move_json_pointer", "path": "package.json", "pointer": "/scripts/publication:bundle", "destination": "/publication:bundle"}, "expected_error": "package.json: JSON pointer '/scripts/publication:bundle'"}])
cases_path.write_text(json.dumps(cases_document, indent=2) + "\n", encoding="utf-8")

changelog_path = ROOT / "CHANGELOG.md"
changelog = changelog_path.read_text(encoding="utf-8")
old_added = "- Added reproducible Medium and LinkedIn rendition packaging for the Thinking Systems article: copy-ready HTML/Markdown/text, deterministic table expansion, durable links, current reviewed publication figures and alt text, LinkedIn cover/SEO/launch-post checks, Medium hero/canonical guidance, and provenance/readiness manifests without creating a second conceptual source."
new_added = "- Added reproducible Medium and LinkedIn rendition packaging for the Thinking Systems article: copy-ready HTML/Markdown/text, deterministic table expansion, durable links, current reviewed publication figures and alt text, LinkedIn cover/SEO/launch-post checks, a self-contained Medium review page plus ordered manual image-upload kit, Medium canonical guidance, and provenance/readiness manifests without creating a second conceptual source."
changelog = changelog.replace(old_added, new_added)
fixed = "- Corrected the platform-specific image transport contract: LinkedIn retains the tested embedded-image copy/paste path, while Medium keeps a complete self-contained visual review page but requires an ordered manual upload of the hero and nine figures because practical iPad testing showed that Medium drops clipboard images; removed the failed remote-image and committed-transport-asset experiment."
if fixed not in changelog:
    changelog = changelog.replace("### Fixed\n", f"### Fixed\n\n{fixed}\n", 1)
changelog_path.write_text(changelog, encoding="utf-8")
